-- Travel Intelligence — schema inicial
-- O banco travel_intelligence já possui estas tabelas criadas.
CREATE TABLE IF NOT EXISTS public.trip_searches (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), origin TEXT NOT NULL, destination TEXT NOT NULL, departure_date DATE NOT NULL, return_date DATE NOT NULL, travelers INTEGER NOT NULL CHECK (travelers BETWEEN 1 AND 6), budget_per_person NUMERIC(12,2) NOT NULL CHECK (budget_per_person > 0), request JSONB NOT NULL DEFAULT '{}'::jsonb, summary TEXT, report TEXT NOT NULL, sources JSONB NOT NULL DEFAULT '[]'::jsonb);
CREATE INDEX IF NOT EXISTS trip_searches_created_at_idx ON public.trip_searches (created_at DESC);
CREATE TABLE IF NOT EXISTS public.price_alerts (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), enabled BOOLEAN NOT NULL DEFAULT TRUE, origin TEXT NOT NULL, destination TEXT NOT NULL, departure_date DATE NOT NULL, return_date DATE, travelers INTEGER NOT NULL DEFAULT 1 CHECK (travelers BETWEEN 1 AND 6), target_price_per_person NUMERIC(12,2) NOT NULL CHECK (target_price_per_person > 0), currency CHAR(3) NOT NULL DEFAULT 'BRL', last_price_per_person NUMERIC(12,2), last_checked_at TIMESTAMPTZ, last_notified_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS price_alerts_enabled_departure_idx ON public.price_alerts (enabled, departure_date);
CREATE TABLE IF NOT EXISTS public.price_observations (id BIGSERIAL PRIMARY KEY, alert_id BIGINT REFERENCES public.price_alerts(id) ON DELETE CASCADE, observed_at TIMESTAMPTZ NOT NULL DEFAULT now(), price_per_person NUMERIC(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'BRL', source TEXT NOT NULL, source_url TEXT, is_live_quote BOOLEAN NOT NULL DEFAULT FALSE, metadata JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS price_observations_alert_observed_idx ON public.price_observations (alert_id, observed_at DESC);
